import{_ as n,o as a,c as t,a2 as p}from"./chunks/framework.DIWxYxwh.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"语音交互/傅里叶变换.md","filePath":"语音交互/傅里叶变换.md","lastUpdated":null}'),e={name:"语音交互/傅里叶变换.md"};function l(i,s,o,r,d,c){return a(),t("div",null,[...s[0]||(s[0]=[p(`<p>傅里叶变换在 CosyVoice3 中的角色，可以概括为一条**“分析—表示—重建”<strong>的链路：音频先经过</strong>短时傅里叶变换（STFT）<strong>被拆解成时间-频率表示，再映射为 Mel 频谱供 Flow Matching 使用；最终 Vocoder 通过</strong>逆短时傅里叶变换（iSTFT）**把频域信息还原回 24 kHz 时域波形。中间的 LLM 处理的是离散语音 Token，不直接涉及傅里叶运算。</p><p>下面从公式、图示、各环节参数三个层面完整展开。</p><hr><h2 id="一、从连续傅里叶变换到-stft-为什么语音必须-分段" tabindex="-1">一、从连续傅里叶变换到 STFT：为什么语音必须“分段” <a class="header-anchor" href="#一、从连续傅里叶变换到-stft-为什么语音必须-分段" aria-label="Permalink to &quot;一、从连续傅里叶变换到 STFT：为什么语音必须“分段”&quot;">​</a></h2><h3 id="_1-连续傅里叶变换-cft" tabindex="-1">1. 连续傅里叶变换（CFT） <a class="header-anchor" href="#_1-连续傅里叶变换-cft" aria-label="Permalink to &quot;1. 连续傅里叶变换（CFT）&quot;">​</a></h3><p>对连续信号 (x(t))，其傅里叶变换定义为：</p><p>[ X(f) = \\int_{-\\infty}^{\\infty} x(t), e^{-j2\\pi ft}, dt ]</p><p>逆变换为：</p><p>[ x(t) = \\int_{-\\infty}^{\\infty} X(f), e^{j2\\pi ft}, df ]</p><p>物理含义：(X(f)) 表示信号中频率 (f) 的成分有多强、相位如何。正变换把“随时间变化”翻译成“由哪些频率组成”，逆变换则反过来。</p><p>但语音是<strong>非平稳信号</strong>——发音内容在几十毫秒内就会变化。对整段语音做一次 CFT，得到的是全局平均频谱，丢失了时间信息。</p><h3 id="_2-短时傅里叶变换-stft" tabindex="-1">2. 短时傅里叶变换（STFT） <a class="header-anchor" href="#_2-短时傅里叶变换-stft" aria-label="Permalink to &quot;2. 短时傅里叶变换（STFT）&quot;">​</a></h3><p>STFT 用滑动窗把信号切成短帧，每帧近似平稳，再逐帧做傅里叶变换：</p><p>[ \\text{STFT}(t, f) = \\int_{-\\infty}^{\\infty} s(\\tau), h^{*}(\\tau - t), e^{-j2\\pi f\\tau}, d\\tau ]</p><p>其中 (s(\\tau)) 是信号，(h(\\tau - t)) 是窗函数（如 Hamming 窗），(*) 表示复共轭。</p><p><strong>核心权衡</strong>：窗长决定频率分辨率，帧移决定时间分辨率。窗越长，频率分得越细，但时间定位越模糊；窗越短则相反。这一权衡由不确定性原理约束：</p><p>[ \\delta t \\cdot \\delta f \\geq \\frac{1}{4\\pi} ]</p><p>CosyVoice3 的 Mel 参数为 <code>n_fft=1920</code>，<code>hop=480</code>，采样率 24 kHz。这意味着：</p><ul><li>每帧覆盖 <strong>1920 个样本 ≈ 80 ms</strong>，频率分辨率约 <strong>12.5 Hz</strong></li><li>帧移 <strong>480 个样本 = 20 ms</strong>，即每 20 ms 产生一帧频谱</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号:  ████████████████████████████████████████</span></span>
<span class="line"><span>窗:    [====]</span></span>
<span class="line"><span>           [====]</span></span>
<span class="line"><span>                [====]</span></span>
<span class="line"><span>                     [====]</span></span>
<span class="line"><span>                          ...</span></span>
<span class="line"><span>       ├─ hop=480 (20ms) ─┤</span></span></code></pre></div><hr><h2 id="二、从-stft-到-mel-频谱-为什么是-80-维" tabindex="-1">二、从 STFT 到 Mel 频谱：为什么是 80 维 <a class="header-anchor" href="#二、从-stft-到-mel-频谱-为什么是-80-维" aria-label="Permalink to &quot;二、从 STFT 到 Mel 频谱：为什么是 80 维&quot;">​</a></h2><p>STFT 输出的是<strong>线性频率轴</strong>上的幅度谱。人耳对频率的感知并非线性：1 kHz 以下分辨较细，高频则越来越粗。Mel 刻度模拟这一特性，把线性频率轴压缩为感知更均匀的刻度。</p><p>CosyVoice3 的 Flow Matching 输出目标为 <strong>80 维 Mel 频谱</strong>。这 80 个维度对应 80 个 Mel 频带，覆盖 0 到 12 kHz（24 kHz 采样的奈奎斯特上限）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>线性频率:  0 ─── 2k ─── 4k ─── 6k ─── 8k ─── 10k ─── 12k (Hz)</span></span>
<span class="line"><span>           │     │      │      │      │       │       │</span></span>
<span class="line"><span>Mel 频带:  ████████████████████████████████████████████████</span></span>
<span class="line"><span>           低频密（分辨细）        高频疏（分辨粗）</span></span>
<span class="line"><span>           共 80 个频带</span></span></code></pre></div><p>所以，<strong>一张 Mel 频谱的坐标含义</strong>是：</p><ul><li><strong>横轴</strong>：时间帧（每帧 20 ms）</li><li><strong>纵轴</strong>：80 个 Mel 频带（从低频到高频）</li><li><strong>颜色/数值</strong>：该时刻该频带的能量强度</li></ul><p>这就是 Flow Matching 要生成的“中间表示”，也是 Vocoder 的输入。</p><hr><h2 id="三、cosyvoice3-中傅里叶相关环节的全景图" tabindex="-1">三、CosyVoice3 中傅里叶相关环节的全景图 <a class="header-anchor" href="#三、cosyvoice3-中傅里叶相关环节的全景图" aria-label="Permalink to &quot;三、CosyVoice3 中傅里叶相关环节的全景图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        参考音频（任意采样率）                      │</span></span>
<span class="line"><span>│                              │                                   │</span></span>
<span class="line"><span>│                    ① 重采样 + 抗混叠滤波                          │</span></span>
<span class="line"><span>│                    （频域设计，防止混叠）                          │</span></span>
<span class="line"><span>│                              ▼                                   │</span></span>
<span class="line"><span>│                    24 kHz PCM 参考音频                           │</span></span>
<span class="line"><span>│                              │                                   │</span></span>
<span class="line"><span>│                    ② STFT（n_fft=1920, hop=480）                │</span></span>
<span class="line"><span>│                              ▼                                   │</span></span>
<span class="line"><span>│                    线性频谱 → Mel 滤波 → 80 维 Mel 频谱           │</span></span>
<span class="line"><span>│                    （作为 Flow 的条件输入）                       │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    LLM（Qwen-based，离散 Token 操作）              │</span></span>
<span class="line"><span>│              文本 Token + 参考 Speech Token → 生成 Speech Token   │</span></span>
<span class="line"><span>│                     ★ 此阶段不涉及傅里叶变换 ★                    │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Flow Matching（Causal DiT）                    │</span></span>
<span class="line"><span>│              Speech Token + 参考 Mel + Speaker Embedding         │</span></span>
<span class="line"><span>│                              ▼                                   │</span></span>
<span class="line"><span>│                    输出：80 维 Mel 频谱（时间 × Mel 频带 × 能量）  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    Vocoder（Causal HiFT）                         │</span></span>
<span class="line"><span>│              ③ 预测幅度/相位 → iSTFT 重建 → 24 kHz 波形            │</span></span>
<span class="line"><span>│              ④ F0 估计 → 谐波源生成（频域正弦源）                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                               │</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>                    24 kHz 流式 PCM 音频输出</span></span></code></pre></div><hr><h2 id="四、vocoder-端的傅里叶-istft-与谐波源" tabindex="-1">四、Vocoder 端的傅里叶：iSTFT 与谐波源 <a class="header-anchor" href="#四、vocoder-端的傅里叶-istft-与谐波源" aria-label="Permalink to &quot;四、Vocoder 端的傅里叶：iSTFT 与谐波源&quot;">​</a></h2><p>CosyVoice3 的声码器是 <strong>Causal HiFT</strong>，其底层技术与 HiFTNet 一脉相承。HiFTNet 的核心设计包含两个傅里叶相关的关键组件：</p><h3 id="_1-逆短时傅里叶变换-istft" tabindex="-1">1. 逆短时傅里叶变换（iSTFT） <a class="header-anchor" href="#_1-逆短时傅里叶变换-istft" aria-label="Permalink to &quot;1. 逆短时傅里叶变换（iSTFT）&quot;">​</a></h3><p>网络不直接逐样本生成波形，而是先预测<strong>短时傅里叶系数</strong>（幅度和相位），再用 iSTFT 把这些频域系数合成为时域波形。这比纯时域卷积更高效，因为频域表示更紧凑。</p><p>iSTFT 的公式本质上是 STFT 的逆运算：</p><p>[ s[n] = \\sum_{k} \\sum_{m} \\text{STFT}(m, k), h[n - mR], e^{j2\\pi k n / N} ]</p><p>其中 (R) 是帧移，(N) 是 FFT 点数。HiFTNet 的消融实验显示，<strong>移除 STFT 模块会导致音质显著下降</strong>（CMOS 降低 0.358），证明频域重建对音质至关重要。</p><h3 id="_2-谐波-plus-噪声源滤波-频域" tabindex="-1">2. 谐波-plus-噪声源滤波（频域） <a class="header-anchor" href="#_2-谐波-plus-噪声源滤波-频域" aria-label="Permalink to &quot;2. 谐波-plus-噪声源滤波（频域）&quot;">​</a></h3><p>HiFTNet 在时频域引入谐波源：利用预训练的 F0 估计网络得到基频，在频域生成正弦谐波源，再与噪声成分结合。这一设计让声码器在保持轻量的同时达到高质量。</p><p>F0 本身对应着语音频谱中<strong>最低的那条谐波轨迹</strong>：</p><ul><li>成年男性：85–180 Hz</li><li>成年女性：165–255 Hz</li><li>这条轨迹在语谱图上就是最下方那条随时间起伏的曲线</li></ul><hr><h2 id="五、采音端-傅里叶在哪里起作用-以及哪里不起作用" tabindex="-1">五、采音端：傅里叶在哪里起作用（以及哪里不起作用） <a class="header-anchor" href="#五、采音端-傅里叶在哪里起作用-以及哪里不起作用" aria-label="Permalink to &quot;五、采音端：傅里叶在哪里起作用（以及哪里不起作用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th style="text-align:center;">是否用傅里叶</th><th>说明</th></tr></thead><tbody><tr><td>麦克风换能</td><td style="text-align:center;">❌</td><td>声波→模拟电信号</td></tr><tr><td><strong>抗混叠滤波</strong></td><td style="text-align:center;">✅ 设计层面</td><td>必须在 ADC 前滤除 (f_s/2) 以上频率，否则采样后混叠无法去除。滤波器设计在频域完成</td></tr><tr><td>ADC 采样+量化</td><td style="text-align:center;">❌</td><td>纯时域操作：每 (1/f_s) 秒读一个电压值</td></tr><tr><td><strong>重采样（如 48k→24k）</strong></td><td style="text-align:center;">✅</td><td>降采样前必须做低通抗混叠，这是你部署参考音频时最易被忽视的环节</td></tr><tr><td><strong>STFT / 特征提取</strong></td><td style="text-align:center;">✅</td><td>采音后的核心分析工具</td></tr></tbody></table><p><strong>关键点</strong>：ADC 采样动作本身不用傅里叶变换，但采样“为什么可行”（奈奎斯特准则）以及采样前的抗混叠设计，都建立在频域分析之上。</p><hr><h2 id="六、对你-4090-部署的直接含义" tabindex="-1">六、对你 4090 部署的直接含义 <a class="header-anchor" href="#六、对你-4090-部署的直接含义" aria-label="Permalink to &quot;六、对你 4090 部署的直接含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>傅里叶相关开销</th><th>优化方向</th></tr></thead><tbody><tr><td>参考音频重采样</td><td>抗混叠滤波（CPU 或 GPU）</td><td>批量预处理，避免推理时重复计算</td></tr><tr><td>Flow → Mel</td><td>STFT 在训练时用于构造目标；推理时 Flow 直接输出 Mel，不跑 STFT</td><td><strong>Flow 的瓶颈在 DiT 计算，不在傅里叶</strong></td></tr><tr><td>Vocoder（HiFT）</td><td>iSTFT 是逐帧密集运算</td><td>分块推理、FP16/BF16；<code>hop=480</code> 决定每 20ms 产出一帧音频</td></tr><tr><td>流式 Chunk</td><td>每 20 ms 一个 Mel 帧，WebSocket 按此粒度推送</td><td>延迟预算 = 帧移 × 流水线缓冲帧数</td></tr></tbody></table><p><strong>一个容易被忽略的点</strong>：你部署时如果参考音频是 44.1 kHz 或 48 kHz，<strong>必须先做低通抗混叠再降到 24 kHz</strong>。否则 12 kHz 以上的成分会混叠进可听频段，污染参考音色和 Speech Token，直接降低合成质量。这是采音/预处理链路中傅里叶思想最实际的应用。</p><hr><h2 id="七、一句话总结" tabindex="-1">七、一句话总结 <a class="header-anchor" href="#七、一句话总结" aria-label="Permalink to &quot;七、一句话总结&quot;">​</a></h2><blockquote><p>CosyVoice3 的傅里叶变换体现在两端：<strong>STFT 把音频变成 Mel 频谱（Flow 的目标与 Vocoder 的输入）</strong>，<strong>iSTFT 把频域系数还原成 24 kHz 波形（Vocoder 的职责）</strong>。LLM 生成离散 Token 的环节是符号操作，不涉及傅里叶运算。你部署时最需要关注的傅里叶相关细节是：参考音频重采样前的抗混叠滤波，以及 Vocoder 端 iSTFT 的分块推理粒度（hop=480，即 20 ms）。</p></blockquote>`,54)])])}const g=n(e,[["render",l]]);export{T as __pageData,g as default};
